"use client";

import React, { useState } from "react";
import { Mail, Clock, Pause, Play } from "lucide-react";

export function CRMEmailSequenceCard() {
  const [active, setActive] = useState(true);

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-border/50 p-5 rounded-2xl shadow-xl select-none font-sans text-foreground">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-1.5">
          <Mail className="w-4 h-4 text-violet-400" />
          <span className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Drip Sequence #1</span>
        </div>
        <button 
          onClick={() => setActive(!active)}
          className="p-1.5 rounded bg-secondary/40 hover:bg-secondary text-xs text-muted-foreground flex items-center gap-0.5"
        >
          {active ? <Pause className="w-3 h-3 text-amber-400" /> : <Play className="w-3 h-3 text-emerald-400" />}
          <span>{active ? "Pause" : "Start"}</span>
        </button>
      </div>

      <div className="space-y-2 text-xs">
        <div className="p-2.5 rounded-xl bg-white/[0.02] border border-white/[0.03] flex items-center justify-between">
          <span>Email #1: Welcome intro</span>
          <span className="text-[10px] text-violet-400 font-bold">Sent 1m ago</span>
        </div>
        <div className="p-2.5 rounded-xl bg-white/[0.02] border border-white/[0.03] flex items-center justify-between">
          <span>Email #2: Feature walkthrough</span>
          <span className="text-[10px] text-muted-foreground/60 font-bold flex items-center gap-0.5"><Clock className="w-3 h-3" /> Wait 2 days</span>
        </div>
      </div>
    </div>
  );
}
